loadEnv()

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const ARTIFACT_PATH = path.join(ROOT, 'artifacts', 'predeploy-bytecodes.json')
const TARGETS = ['l2'] as const

type TargetOption = (typeof TARGETS)[number]

interface CliOptions {
  l2Rpc?: string
  funderPrivateKey?: string
  target: TargetOption
  contracts?: string[]
  dryRun?: boolean
  confirm?: boolean
  gasEstimate?: boolean
  gasBuffer: number
}

interface GasEstimateResult {
  key: string
  label: string
  fundingAddress: string
  hardcodedAmount: string
  txGasPrice: bigint
  txGasLimit: bigint
  maxCost: bigint         // gasPrice * gasLimit — minimum balance required for the node to accept the tx
  estimatedGasUsed: bigint | null
  estimatedCost: bigint | null    // estimatedGasUsed * gasPrice — likely actual spend
  expectedLeftover: bigint | null // maxCost - estimatedCost — refunded to deployer after tx
  deployerNonce: number           // must be 0 for pre-signed tx to work
  alreadyDeployed: boolean
  estimateError?: string
}

interface DeploymentArtifact {
  label: string
  abi: unknown[]
  bytecode: string
  compiler: string
  language: string
}

interface ArtifactEntry extends DeploymentArtifact {
  key: string
}

interface PreSignedDeployment {
  key: string
  label: string
  deployedAddress: string
  fundingAddress: string
  fundingAmount: string
  rawTransaction: string
}

interface DeploymentSummary {
  chain: 'l2'
  key: string
  label: string
  deployedAddress?: string
  transactionHash?: string
  fundingAddress?: string
  fundingAmount?: string
  funded?: boolean
  published?: boolean
}

