const program = new Command()
  .option('--l2-rpc <url>', 'L2 RPC URL', process.env.L2_RPC_URL)
  .option('--funder-private-key <hex>', 'Private key to fund deployment addresses (0x-prefixed)', process.env.FUNDER_PRIVATE_KEY)
  .option('--target <target>', 'Deployment target: l2', (value: string) => value.toLowerCase(), 'l2')
  .option('--contracts <list>', 'Comma-separated contract keys (defaults to all)', (value: string) => value.split(',').map(entry => entry.trim()).filter(Boolean))
  .option('--dry-run', 'Print actions without broadcasting transactions', false)
  .option('--confirm', 'Skip interactive confirmation prompt', false)
  .option('--gas-estimate', 'Estimate actual gas costs on L2 and compare with hardcoded funding amounts (requires --l2-rpc)', false)
  .option('--gas-buffer <percent>', 'Extra % added on top of estimated gas cost when funding deployer addresses (default: 20)', (v) => parseInt(v, 10), 20)

program.parse(process.argv)
const options = program.opts<CliOptions>()

if (!TARGETS.includes(options.target)) {
  console.error(`Invalid target '${options.target}'. Expected: l2`)
  process.exit(1)
}

if (!options.dryRun && !options.gasEstimate && !options.l2Rpc) {
  console.error('Missing L2 RPC URL. Provide --l2-rpc or set L2_RPC_URL in .env.')
  process.exit(1)
}

if (options.gasEstimate && !options.l2Rpc) {
  console.error('--gas-estimate requires --l2-rpc.')
  process.exit(1)
}

if (!options.dryRun && !options.gasEstimate && !options.funderPrivateKey) {
  console.error('Missing funder private key. Provide --funder-private-key or set FUNDER_PRIVATE_KEY in .env.')
  process.exit(1)
}

function normalizePrivateKey(key: string): string {
  return key.startsWith('0x') ? key : `0x${key}`
}

async function loadDeployments(selectedKeys?: string[]): Promise<PreSignedDeployment[]> {
  let deployments = PRE_SIGNED_DEPLOYMENTS

  if (selectedKeys && selectedKeys.length > 0) {
    const availableKeys = new Set(PRE_SIGNED_DEPLOYMENTS.map(d => d.key))
    const missing = selectedKeys.filter(key => !availableKeys.has(key))
    if (missing.length) {
      throw new Error(`Unknown contract key(s): ${missing.join(', ')}. Available: ${Array.from(availableKeys).join(', ')}`)
    }
    const keySet = new Set(selectedKeys)
    deployments = deployments.filter(({ key }) => keySet.has(key))
  }

  return deployments
}

function askConfirmation(question: string): Promise<boolean> {
  return new Promise(resolve => {
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
    rl.question(question, answer => {
      rl.close()
      resolve(answer.trim().toLowerCase() === 'y')
    })
  })
}

async function checkBalance(provider: JsonRpcProvider, address: string): Promise<bigint> {
  return await provider.getBalance(address)
}

function formatEther(wei: bigint): string {
  // Simple formatting: divide by 10^18 and show up to 6 decimals
  const ethValue = Number(wei) / 1e18
  return ethValue.toFixed(6)
}

async function gasEstimateOnL2(params: {
  deployments: PreSignedDeployment[]
  rpcUrl: string
}): Promise<GasEstimateResult[]> {
  const { deployments, rpcUrl } = params
  const provider = new JsonRpcProvider(rpcUrl)
  const results: GasEstimateResult[] = []

  console.log('\n[L2] Running gas estimation...')

  for (const deployment of deployments) {
    console.log(`\n  ${deployment.label}`)

    // Decode the pre-signed transaction to extract gas parameters
    const parsedTx = Transaction.from(deployment.rawTransaction)
    const txGasPrice = parsedTx.gasPrice ?? BigInt(0)
    const txGasLimit = BigInt(parsedTx.gasLimit)
    const maxCost = txGasPrice * txGasLimit

    // Check if already deployed
    const code = await provider.getCode(deployment.deployedAddress)
    const alreadyDeployed = code !== '0x'
    if (alreadyDeployed) {
      console.log(`    ✓ Already deployed at ${deployment.deployedAddress}`)
    }

    // Check deployer nonce — must be 0 for the pre-signed tx to be usable.
    // If the contract is already deployed the nonce will be >= 1, which is expected.
    const deployerNonce = await provider.getTransactionCount(deployment.fundingAddress)
    if (!alreadyDeployed) {
      if (deployerNonce !== 0) {
        console.log(`    ⚠ WARNING: Deployer nonce is ${deployerNonce} (expected 0). Pre-signed tx cannot be broadcast!`)
      } else {
        console.log(`    ✓ Deployer nonce: 0`)
      }
    }

    // Estimate gas by simulating the deployment call.
    // When already deployed the deployer nonce is >= 1, so the CREATE targets a
    // fresh address — the simulation still succeeds and gives accurate gas figures.
    let estimatedGasUsed: bigint | null = null
    let estimateError: string | undefined

    try {
      estimatedGasUsed = await provider.estimateGas({
        from: deployment.fundingAddress,
        data: parsedTx.data,
        value: parsedTx.value
      })
      console.log(`    Gas limit (tx):    ${txGasLimit.toLocaleString()}`)
      console.log(`    Estimated gas:     ${estimatedGasUsed.toLocaleString()} (${((Number(estimatedGasUsed) / Number(txGasLimit)) * 100).toFixed(1)}% of limit)`)
    } catch (err: any) {
      estimateError = err.message
      console.log(`    ⚠ Gas estimation failed: ${err.message}`)
    }

    const estimatedCost = estimatedGasUsed !== null ? estimatedGasUsed * txGasPrice : null
    const expectedLeftover = estimatedCost !== null ? maxCost - estimatedCost : null

    results.push({
      key: deployment.key,
      label: deployment.label,
      fundingAddress: deployment.fundingAddress,
      hardcodedAmount: deployment.fundingAmount,
      txGasPrice,
      txGasLimit,
      maxCost,
      estimatedGasUsed,
      estimatedCost,
      expectedLeftover,
      deployerNonce,
      alreadyDeployed,
      estimateError
    })
  }

  return results
}

async function deployOnL2(params: {
  deployments: PreSignedDeployment[]
  rpcUrl?: string
  funderPrivateKey?: string
  dryRun: boolean
  gasBuffer: number
}): Promise<DeploymentSummary[]> {
  const { deployments, rpcUrl, funderPrivateKey, dryRun, gasBuffer } = params

  if (dryRun) {
    console.log(`\n[L2] Dry run mode.`)
    console.log('No RPC checks or transactions will be broadcast.')
    return deployments.map(deployment => ({
      chain: 'l2' as const,
      key: deployment.key,
      label: deployment.label,
      deployedAddress: deployment.deployedAddress,
      fundingAddress: deployment.fundingAddress,
      fundingAmount: deployment.fundingAmount
    }))
  }

  const provider = new JsonRpcProvider(rpcUrl)
  const funderWallet = new Wallet(funderPrivateKey!, provider)
  const results: DeploymentSummary[] = []

  console.log('\n[L2] Checking funding addresses and deploying contracts...')
  console.log(`Funder address: ${funderWallet.address}`)

  for (const deployment of deployments) {
    console.log(`\n[L2] ${deployment.label}`)
    console.log(`  Key: ${deployment.key}`)
    console.log(`  Expected address: ${deployment.deployedAddress}`)
    console.log(`  Funding address: ${deployment.fundingAddress}`)
    console.log(`  Required funding: ${deployment.fundingAmount} ETH`)

    // Check if already deployed
    const code = await provider.getCode(deployment.deployedAddress)
    if (code !== '0x') {
      console.log(`  ✓ Already deployed (code exists at ${deployment.deployedAddress})`)
      results.push({
        chain: 'l2',
        key: deployment.key,
        label: deployment.label,
        deployedAddress: deployment.deployedAddress,
        fundingAddress: deployment.fundingAddress,
        fundingAmount: deployment.fundingAmount,
        funded: true,
        published: false // Already exists, not published by us
      })
      continue
    }

    // Estimate actual gas cost for this deployment and use that instead of the
    // hardcoded fundingAmount, so we don't over-fund the deployer address.
    const parsedTx = Transaction.from(deployment.rawTransaction)
    const txGasPrice = parsedTx.gasPrice ?? BigInt(0)
    const txGasLimit = BigInt(parsedTx.gasLimit)
    let requiredWei: bigint

    try {
      const estimatedGas = await provider.estimateGas({
        from: deployment.fundingAddress,
        data: parsedTx.data,
        value: parsedTx.value
      })
      // Apply the configurable buffer on top of the estimate
      const bufferedGas = estimatedGas * BigInt(100 + gasBuffer) / BigInt(100)
      requiredWei = bufferedGas * txGasPrice
      console.log(`  Gas estimate: ${estimatedGas.toLocaleString()} (+ ${gasBuffer}% buffer → funding ${formatEther(requiredWei)} ETH vs hardcoded ${deployment.fundingAmount} ETH)`)
    } catch (err: any) {
      // Fall back to the hardcoded amount if estimation fails
      requiredWei = parseEther(deployment.fundingAmount)
      console.log(`  ⚠ Gas estimation failed (${err.message}), falling back to hardcoded ${deployment.fundingAmount} ETH`)
    }

    // Check funding address balance
    const balance = await checkBalance(provider, deployment.fundingAddress)
    const isFunded = balance >= requiredWei

    console.log(`  Funding balance: ${formatEther(balance)} ETH (required: ${formatEther(requiredWei)} ETH)`)

    if (!isFunded) {
      const topUp = requiredWei - balance
      console.log(`  ⚠ Insufficient balance. Topping up deployer with ${formatEther(topUp)} ETH...`)
      try {
        const fundingTx = await funderWallet.sendTransaction({
          to: deployment.fundingAddress,
          value: topUp
        })
        console.log(`  📤 Funding tx sent: ${fundingTx.hash}`)
        await fundingTx.wait()
        console.log(`  ✓ Funding confirmed`)
      } catch (error: any) {
        console.error(`  ✗ Failed to fund address: ${error.message}`)
        results.push({
          chain: 'l2',
          key: deployment.key,
          label: deployment.label,
          deployedAddress: deployment.deployedAddress,
          fundingAddress: deployment.fundingAddress,
          fundingAmount: deployment.fundingAmount,
          funded: false,
          published: false
        })
        continue
      }
    } else {
      console.log(`  ✓ Already funded`)
    }

    // Publish the pre-signed transaction
    console.log(`  ✓ Funded. Publishing pre-signed transaction...`)
    try {
      const result = execSync(
        `cast publish ${deployment.rawTransaction} --rpc-url ${rpcUrl}`,
        { encoding: 'utf8', stdio: 'pipe' }
      )
      const txHash = result.trim()
      console.log(`  ✓ Published tx: ${txHash}`)
      
      // Verify deployment by checking contract code
      console.log(`  🔍 Verifying deployment...`)
      try {
        const codeResult = execSync(
          `cast code ${deployment.deployedAddress} --rpc-url ${rpcUrl}`,
          { encoding: 'utf8', stdio: 'pipe' }
        )
        const code = codeResult.trim()
        
        if (code === '0x' || code === '' || code === '0x0') {
          console.error(`  ✗ Verification failed: No code at ${deployment.deployedAddress}`)
          results.push({
            chain: 'l2',
            key: deployment.key,
            label: deployment.label,
            deployedAddress: deployment.deployedAddress,
            transactionHash: txHash,
            fundingAddress: deployment.fundingAddress,
            fundingAmount: deployment.fundingAmount,
            funded: true,
            published: false
          })
          continue
        }
        
        console.log(`  ✓ Verified: Contract deployed at ${deployment.deployedAddress}`)
        console.log(`  ✓ Code size: ${(code.length - 2) / 2} bytes`)
        
        results.push({
          chain: 'l2',
          key: deployment.key,
          label: deployment.label,
          deployedAddress: deployment.deployedAddress,
          transactionHash: txHash,
          fundingAddress: deployment.fundingAddress,
          fundingAmount: deployment.fundingAmount,
          funded: true,
          published: true
        })
      } catch (verifyError: any) {
        console.error(`  ⚠ Verification check failed: ${verifyError.message}`)
        console.log(`  ℹ Transaction was published but verification couldn't complete`)
        results.push({
          chain: 'l2',
          key: deployment.key,
          label: deployment.label,
          deployedAddress: deployment.deployedAddress,
          transactionHash: txHash,
          fundingAddress: deployment.fundingAddress,
          fundingAmount: deployment.fundingAmount,
          funded: true,
          published: true
        })
      }
    } catch (error: any) {
      console.error(`  ✗ Failed to publish: ${error.message}`)
      results.push({
        chain: 'l2',
        key: deployment.key,
        label: deployment.label,
        deployedAddress: deployment.deployedAddress,
        fundingAddress: deployment.fundingAddress,
        fundingAmount: deployment.fundingAmount,
        funded: true,
        published: false
      })
    }
  }

  return results
}

async function main() {
  const deployments = await loadDeployments(options.contracts)
  console.log(`Loaded ${deployments.length} pre-signed deployment(s).`)

  console.log('\nSelected options:')
  console.log(`  Target: ${options.target}`)
  console.log(`  L2 RPC: ${options.l2Rpc ?? 'n/a'}`)
  console.log(`  Dry run: ${options.dryRun ? 'yes' : 'no'}`)
  console.log(`  Gas estimate: ${options.gasEstimate ? 'yes' : 'no'}`)
  console.log(`  Gas buffer: ${options.gasBuffer}%`)

  console.log('\nContracts to deploy:')
  for (const deployment of deployments) {
    console.log(`  - ${deployment.label} (${deployment.key})`)
    console.log(`    Expected address: ${deployment.deployedAddress}`)
    console.log(`    Funding address:  ${deployment.fundingAddress}`)
    console.log(`    Required amount:  ${deployment.fundingAmount} ETH`)
  }

  // Gas estimate mode: connect to L2, estimate actual costs, check deployer nonces
  if (options.gasEstimate) {
    const estimates = await gasEstimateOnL2({
      deployments,
      rpcUrl: options.l2Rpc!
    })

    console.log('\n' + '='.repeat(80))
    console.log('GAS ESTIMATE SUMMARY')
    console.log('='.repeat(80))

    let totalHardcoded = BigInt(0)
    let totalMaxCost = BigInt(0)
    let totalEstimated = BigInt(0)
    let undeployedCount = 0

    for (const est of estimates) {
      console.log(`\n${est.label} (${est.key})`)
      console.log(`  Funding address: ${est.fundingAddress}`)

      if (est.alreadyDeployed) {
        console.log(`  Status:          ✓ Already deployed`)
      } else {
        undeployedCount++
        const hardcodedWei = parseEther(est.hardcodedAmount)
        totalHardcoded += hardcodedWei
        totalMaxCost += est.maxCost

        const nonceStatus = est.deployerNonce === 0
          ? '✓ 0 (valid)'
          : `⚠ ${est.deployerNonce} — NONCE BURNED, pre-signed tx unusable!`
        console.log(`  Deployer nonce:  ${nonceStatus}`)
        console.log(`  Min to send:     ${formatEther(est.maxCost)} ETH  (gasPrice × gasLimit — node rejects tx if below this)`)
        console.log(`  Hardcoded:       ${est.hardcodedAmount} ETH`)

        const hardcodedOverage = hardcodedWei - est.maxCost
        if (hardcodedOverage > BigInt(0)) {
          console.log(`  Hardcoded overage: +${formatEther(hardcodedOverage)} ETH above min (wasted if sent as-is)`)
        }
      }

      console.log(`  Gas price (tx):  ${formatUnits(est.txGasPrice, 'gwei')} gwei`)
      console.log(`  Gas limit (tx):  ${est.txGasLimit.toLocaleString()}`)

      if (est.estimatedGasUsed !== null && est.estimatedCost !== null && est.expectedLeftover !== null) {
        if (!est.alreadyDeployed) totalEstimated += est.estimatedCost
        console.log(`  Estimated gas:   ${est.estimatedGasUsed.toLocaleString()} used`)
        console.log(`  Estimated cost:  ${formatEther(est.estimatedCost)} ETH`)
        console.log(`  Expected refund: ${formatEther(est.expectedLeftover)} ETH left in deployer after tx`)
      } else if (est.estimateError) {
        if (!est.alreadyDeployed) totalEstimated += est.maxCost // fall back to max cost if estimation failed
        console.log(`  Gas estimate:    ⚠ Failed (${est.estimateError})`)
        if (!est.alreadyDeployed) console.log(`  Recommendation:  Send min required (${formatEther(est.maxCost)} ETH)`)
      }
    }

    if (undeployedCount > 0) {
      console.log('\n' + '-'.repeat(80))
      console.log('TOTALS (undeployed contracts only)')
      console.log(`  Hardcoded total:   ${formatEther(totalHardcoded)} ETH`)
      console.log(`  Min required:      ${formatEther(totalMaxCost)} ETH  (sum of gasPrice × gasLimit per tx)`)
      if (totalEstimated > BigInt(0)) {
        console.log(`  Estimated actual:  ${formatEther(totalEstimated)} ETH  (likely spend based on gas estimation)`)
      }
      const hardcodedSavings = totalHardcoded - totalMaxCost
      if (hardcodedSavings > BigInt(0)) {
        console.log(`  Overfunding:       ${formatEther(hardcodedSavings)} ETH above min (hardcoded vs actual minimum)`)
      }
      console.log('\nNote: Send at least "min required" per deployer address. Unused gas is refunded')
      console.log('      to the deployer address after deployment, not back to the funder.')
    }

    return
  }

  if (!options.confirm && !options.dryRun) {
    const confirmed = await askConfirmation('\nProceed with deployment checks and publishing? (y/N): ')
    if (!confirmed) {
      console.log('Aborted by user.')
      process.exit(0)
    }
  }

  const summary = await deployOnL2({
    deployments,
    rpcUrl: options.l2Rpc,
    funderPrivateKey: options.funderPrivateKey ? normalizePrivateKey(options.funderPrivateKey) : undefined,
    dryRun: Boolean(options.dryRun),
    gasBuffer: options.gasBuffer
  })

  console.log('\n' + '='.repeat(60))
  console.log('DEPLOYMENT SUMMARY')
  console.log('='.repeat(60))
  
  for (const item of summary) {
    console.log(`\n[${item.chain.toUpperCase()}] ${item.label}`)
    console.log(`  Key:              ${item.key}`)
    console.log(`  Expected Address: ${item.deployedAddress}`)
    
    if (item.fundingAddress) {
      console.log(`  Funding Address:  ${item.fundingAddress}`)
      console.log(`  Required Amount:  ${item.fundingAmount} ETH`)
    }
    
    if (item.funded !== undefined) {
      console.log(`  Funded:           ${item.funded ? '✓ Yes' : '✗ No'}`)
    }
    
    if (item.published !== undefined) {
      console.log(`  Published:        ${item.published ? '✓ Yes' : '✗ No (already exists or failed)'}`)
    }
    
    if (item.transactionHash) {
      console.log(`  Transaction:      ${item.transactionHash}`)
    }
  }

  console.log('\n' + '='.repeat(60))
  
  if (options.dryRun) {
    console.log('\nDry run complete. No transactions were broadcast.')
  } else {
    const needsFunding = summary.filter(s => s.funded === false)
    const failed = summary.filter(s => s.funded === true && s.published === false && !s.transactionHash)
    
    if (needsFunding.length > 0) {
      console.log('\n⚠ Action Required:')
      console.log('The following contracts need funding before they can be deployed:')
      for (const item of needsFunding) {
        console.log(`  - Send ${item.fundingAmount} ETH to ${item.fundingAddress}`)
        console.log(`    (for ${item.label})`)
      }
    }
    
    if (failed.length > 0) {
      console.log('\n✗ Some deployments failed. Check the logs above for details.')
    }
    
    const succeeded = summary.filter(s => s.published === true)
    if (succeeded.length > 0) {
      console.log(`\n✓ Successfully deployed ${succeeded.length} contract(s).`)
    }
  }
}

main().catch(error => {
  console.error('Deployment failed:', error)
  process.exit(1)
})
